"use strict";(globalThis.webpackChunksanctuary_amongst_the_starts=globalThis.webpackChunksanctuary_amongst_the_starts||[]).push([[8409],{1119(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>i,default:()=>d,frontMatter:()=>o,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"world-information/locations/inner-system/mercury","title":"Mercury","description":"---","source":"@site/docs/world-information/locations/inner-system/mercury.md","sourceDirName":"world-information/locations/inner-system","slug":"/world-information/locations/inner-system/mercury","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/inner-system/mercury","draft":false,"unlisted":false,"editUrl":"https://github.com/kaelynj/sanctuary-amongst-the-stars/docs/world-information/locations/inner-system/mercury.md","tags":[],"version":"current","frontMatter":{},"sidebar":"loreSidebar","previous":{"title":"Mars","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/inner-system/mars"},"next":{"title":"Sol","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/inner-system/sol"}}');var s=n(4848),a=n(8453);const o={},i="Mercury",l={},h=[{value:"Mercurials",id:"mercurials",level:2},{value:"Al-Hamadhanj",id:"al-hamadhanj",level:3},{value:"Cannon",id:"cannon",level:3},{value:"The Egg",id:"the-egg",level:2},{value:"Lumina",id:"lumina",level:3}];function c(e){const t={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"mercury",children:"Mercury"})}),"\n",(0,s.jsx)(t.hr,{}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Posted by:"})," ",(0,s.jsx)(t.em,{children:"The Well of the Ocean is Water Aflame"})]}),"\n",(0,s.jsx)(t.p,{children:"Sol's swiftest island is Mercury. It orbits in less than ninety days, but turns so slowly that a face may be exposed to the sun for nearly sixty of those days. The lack of atmosphere provides no blanket against Sol's light, and temperatures range over 620 degrees between day and night. The sun's daylight gaze overhead is fierce enough to melt metal, but at night the surface is as frigid as space. The terminator line moves slowly enough that a transhuman on foot could keep ahead of it at a steady pace."}),"\n",(0,s.jsx)(t.p,{children:"Sol attracts many stray travelers of rock and asteroid, and Mercury takes the blows as they cross its path, leaving the surface of the planet covered in pockmarks and craters. Alternating heat and cold further breaks the rock, covering the surface in dust."}),"\n",(0,s.jsx)(t.h2,{id:"mercurials",children:"Mercurials"}),"\n",(0,s.jsx)(t.p,{children:"The residents of Mercury must be hardy to live in extremes of light and dark and dust. But there is little loyalty to Mercury as a home. Exposed heavy metals lie near the surfaces and are easily mined. Corporations mine Mercury's bones and harvest the sunlight of Sol to profit elsewhere. Solar cells coat every crafted surface to best capture Sol's gift, powering equipment. Hypercorps such as Tolstoj Mining Concern, the Vyasa Workers Cooperative, Jaehon Offworld, and Noonday Mining turn the efforts of their miners into profit. The isolation and difficulty of escape leads hypercorps to enlist prisoners who serve out their sentences -- well-earned or falsely framed -- working in the mining camps."}),"\n",(0,s.jsxs)(t.p,{children:["Those who are not with a corporation survive in the shadow. These ",(0,s.jsx)(t.em,{children:"sifters"})," live nomadically, following the night cycle of the planet to avoid the temperature spikes of the day.  The sifters are independent people and know the secrets of Mercury should they be asked, but they will not share without payment."]}),"\n",(0,s.jsx)(t.p,{children:"Mercury is tiny and isolated, so the production of antimatter is safest here and the intense light provides enough energy for the work. Antimatter powers spacecraft drivers for voyaging and the most dangerous of weapons, making the research worth the risk for groups such as Omnicor, Gammax, Direct Action, and Fa Jing."}),"\n",(0,s.jsx)(t.h3,{id:"al-hamadhanj",children:"Al-Hamadhanj"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Habitat Type:"})," Tin Can/Subsurface"]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Allegiance:"})," Sifter"]}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"The modules of this sifter capital are tucked under the sand and into the edges of a crater for safety in the extreme temperatures. This city is a gathering site for sifters, a place to rest, trade, and seek out news and services. Information and gear may be had and discretion sought for the more clandestine project."}),"\n",(0,s.jsx)(t.h3,{id:"cannon",children:"Cannon"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Habitat Type:"})," Dome"]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Allegiance:"})," Jaehon Offworld"]}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"Cannon is the largest habitat on Mercury. It is also mobile, crawling on massive tracks. Ten-thousand individuals loyal to the hypercorp Jaehon reside here. This city-sized mass driver pauses at each mine to launch giant ingots of heavy metals into space for delivery to ships overhead. Cannon travels the edge of the Caloris basin and the northern hemisphere in its journey between camps."}),"\n",(0,s.jsx)(t.h2,{id:"the-egg",children:"The Egg"}),"\n",(0,s.jsx)(t.p,{children:"Mercury holds mysteries as close as Sol does, and the Egg is one of them. From a distance it does not appear to be a weapon. A pale gray ovoid of unknown material, the Egg orbits above the surface of Mercury. Left by the Factors in AF8, the Planetary Consortium declared the Egg off limits, overruling those who thought it safer destroyed. The Factors offer no explanation, they only ask us to leave it be. So far we have, though not without question or protest. Some speculate it watches over Caloris 18, site of a TITAN outbreak on Mercury during the Fall. Others believe its purpose is to monitor the Vulcanoid Gate from afar."}),"\n",(0,s.jsx)(t.h3,{id:"lumina",children:"Lumina"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Habitat Type:"})," Dome"]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Allegiance:"})," Independent (Hypercorp)"]}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"Near the northern pole lies Lumina. Here energy is captured by solar panel fields lit at all times by the sun. This powers nuclear, radiochemical, and particle physics research, including manufacturing isotopes and the extraction of fissionables. Many hypercorps hold interests here, making it a shared resource as well as a resting place for the hyperelites who come to enjoy the spas and private meeting facilities."})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>i});var r=n(6540);const s={},a=r.createContext(s);function o(e){const t=r.useContext(a);return r.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),r.createElement(a.Provider,{value:t},e.children)}}}]);